(()=>{'use strict';let session=null,version=0,controller=null,story=null;const notice='For fun only — inspired by traditional palmistry, not a factual prediction.';const q=s=>document.querySelector(s);const section=document.createElement('section');section.id='fun-reading';section.className='reading section-pad fun-reading';section.innerHTML=`<p class="eyebrow">A LITTLE MAGIC / FOR FUN ONLY</p><h2>Palmistry stories.<br><em>Let curiosity play.</em></h2><p class="fun-intro">A playful, imagined chapter inspired by traditional palmistry. No factual future prediction.</p><div class="fun-notice">✦ For fun only — not a factual prediction.<br><small>විනෝදාස්වාදය සඳහා පමණි. සැබෑ අනාගත අනාවැකියක් නොවේ.</small></div><div id="fun-empty" class="compact-empty">Analyze both palms in the studio first. Then choose a theme and create your story. <a href="#scanner">Open the palm studio ↗</a></div><div id="fun-controls" hidden><label class="fun-theme">CHOOSE YOUR STORY THEME<select id="fun-theme"><option value="adventure">Adventure & possibilities</option><option value="connection">Friendship & connection</option><option value="purpose">Creativity & purpose</option></select></label><details class="fun-manual"><summary>Optional: choose your own line symbols <span>+</span></summary><p>Look at your photograph and select shapes if you wish. These are manual storytelling choices, not verified line classifications. Leave them unknown when unsure.</p><div class="fun-choices">${['heart','head','life','fate'].map(key=>`<label>${key[0].toUpperCase()+key.slice(1)} line<select data-fun-line="${key}" aria-label="${key} line storytelling symbol"><option value="unknown">Unknown / leave out</option><option value="curved">Curved symbol</option><option value="straight">Straight symbol</option><option value="not-visible">Not visible / leave out</option></select></label>`).join('')}</div></details><button class="primary" id="make-fun-story">✦ Create my for-fun reading</button></div><p id="fun-status" role="status" class="fine"></p><div id="fun-output" hidden><span class="engine-badge" id="fun-mode"></span><h3 id="fun-title"></h3><p id="fun-basis" class="fine"></p><div id="fun-chapters" class="report-grid"></div><p class="fun-notice" id="fun-output-notice"></p><button class="outline" id="download-fun-story">↓ Download story JSON</button></div>`;
q('#reading').after(section);const jump=document.createElement('button');jump.type='button';jump.className='outline';jump.textContent='✦ For Fun Reading';jump.onclick=()=>section.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth',block:'start'});q('#export-report').before(jump);const style=document.createElement('style');style.textContent=`.fun-reading{background:radial-gradient(ellipse at 20% 20%,#63304744,transparent 65%),radial-gradient(ellipse at 90% 80%,#02543c44,transparent 65%),#12121d}.fun-intro{max-width:650px;font-size:12px;line-height:2;color:#c9c1b6}.fun-notice{padding:18px 22px;border:1px solid #d4ad6555;background:#c48f3110;color:#f0d29c;font-size:11px;line-height:1.9}.fun-notice small{font-size:10px;color:#b9cfb8}#fun-controls{margin-top:28px}.fun-theme{display:block;font-size:8px;letter-spacing:2px;color:#e0bd80}.fun-reading select{display:block;background:#152922;border:1px solid #c5a26866;color:#eddfc3;padding:13px;font:11px Manrope,Arial;margin-top:10px;max-width:100%;min-width:220px}.fun-manual{border-block:1px solid #d9b97830;padding:20px 0;margin:25px 0}.fun-manual summary{font-size:11px;cursor:pointer;color:#e3c28c}.fun-manual>p{font-size:10px;line-height:1.9;max-width:700px;color:#b5c6b4}.fun-choices{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px;margin-top:25px}.fun-choices label{font-size:11px;color:#cdbfa6}.fun-choices select{width:100%;min-width:0}#fun-output>h3{font:43px 'Cormorant Garamond',Georgia;color:#f1d4a5;margin:25px 0}#fun-output{margin-top:30px}#fun-chapters .story-icon{font-size:27px;color:#eac37c}#download-fun-story{margin-top:10px}@media(max-width:600px){.fun-choices{grid-template-columns:1fr}.fun-reading h2{font-size:43px}#fun-output>h3{font-size:34px}}`;document.head.append(style);
function reset(){version++;if(controller)controller.abort();controller=null;session=null;story=null;q('#fun-controls').hidden=true;q('#fun-output').hidden=true;q('#fun-empty').hidden=false;q('#fun-chapters').replaceChildren();q('#fun-title').textContent=q('#fun-basis').textContent=q('#fun-status').textContent=q('#fun-mode').textContent='';q('#make-fun-story').disabled=false;q('#make-fun-story').textContent='✦ Create my for-fun reading';q('#fun-theme').value='adventure';section.querySelectorAll('[data-fun-line]').forEach(s=>s.value='unknown')}
window.addEventListener('palma:clear',reset);window.addEventListener('palma:analysis',e=>{reset();session=e.detail;q('#fun-empty').hidden=true;q('#fun-controls').hidden=false;q('#fun-status').textContent='Your palm session is ready. Choose a theme for a fictional, symbolic reading.'});
function localStory(theme,choices){const themes={adventure:['The lantern-lit crossroads','Imagine a little golden compass resting in your hand. In this invented chapter, an unfamiliar doorway opens onto a new hobby, an interesting idea, or a place you have never explored. The story belongs to curiosity, not destiny.'],connection:['The garden of little connections','Picture a garden where each lantern holds a kind word. In this fictional chapter, a warm conversation and a small thoughtful gesture become the brightest treasures. This is a friendship-themed story, not a relationship forecast.'],purpose:['The maker’s next chapter','Imagine a quiet workshop full of sketches and possibility. In this invented chapter, you choose one small creative project and let patience turn it into something of your own. This is a story about making, not a career prediction.']};const t=themes[theme],curved=Object.values(choices).includes('curved'),counts=Object.fromEntries(['left','right'].map(s=>[s,session.hands[s]?.features?.length||0]));return{mode:'local-story',title:t[0],notice,theme,choices,basis:`Your images contain ${counts.left} left-image and ${counts.right} right-image candidate segments. They are not verified named palm lines. This authored story uses your selected theme and optional symbols, not a forecast from the photos.`,chapters:[{title:'Your imagined next chapter',body:t[1]},{title:'A symbol to carry',body:`Borrow the traditional symbols of heart as connection, head as imagination, and fate as direction. ${curved?'Your curved-symbol choice becomes a winding garden path in this story.':'Picture a lantern-lined avenue as your story’s setting.'} These are creative metaphors, not established facts about you.`},{title:'A playful invitation',body:'Write one sentence about a possibility you would enjoy exploring. Treat it as a creative prompt you choose for yourself, not an instruction or a prediction from your palm.'}]}}
function show(result){story=result;q('#fun-title').textContent=result.title;q('#fun-basis').textContent=result.basis;q('#fun-output-notice').textContent=notice;q('#fun-mode').textContent=result.mode==='local-story'?'LOCAL AUTHORED STORY · NO LIVE AI':result.mode==='local-story-fallback'?'LOCAL STORY · LIVE AI UNAVAILABLE':result.mode.toUpperCase()+' · AI STORY';q('#fun-chapters').replaceChildren();result.chapters.forEach((c,i)=>{const a=document.createElement('article'),icon=document.createElement('span'),h=document.createElement('h3'),p=document.createElement('p');icon.className='story-icon';icon.textContent=['✧','♡','✦'][i];h.textContent=c.title;p.textContent=c.body;a.append(icon,h,p);q('#fun-chapters').append(a)});q('#fun-output').hidden=false;q('#fun-status').textContent=result.provider_note||'Your story is ready. For fun only.'}
q('#make-fun-story').onclick=async()=>{if(!session)return;const mine=version,theme=q('#fun-theme').value,choices=Object.fromEntries([...section.querySelectorAll('[data-fun-line]')].map(s=>[s.dataset.funLine,s.value]));q('#make-fun-story').disabled=true;q('#make-fun-story').textContent='✦ Weaving your story…';q('#fun-status').textContent='Creating an imagined chapter from your chosen symbols…';q('#fun-output').hidden=true;controller=new AbortController();const timeout=setTimeout(()=>controller?.abort(),90000);try{let result;if(session.backend&&session.scan_id){const response=await fetch('/api/fun-reading',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({scan_id:session.scan_id,theme,choices}),signal:controller.signal});const data=await response.json();if(!response.ok||!data.ok)throw Error(data.error||'The story service could not respond.');result=data.story}else result=localStory(theme,choices);if(mine!==version)return;show(result)}catch(e){if(mine===version)q('#fun-status').textContent=e.name==='AbortError'?'Story creation timed out. Try again.':e.message}finally{clearTimeout(timeout);if(mine===version){q('#make-fun-story').disabled=false;q('#make-fun-story').textContent='✦ Create another for-fun reading';controller=null}}};
q('#download-fun-story').onclick=()=>{if(!story)return;const blob=new Blob([JSON.stringify({feature:'PALMA For Fun',...story,notice},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='PALMA-For-Fun-Story.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)};
})();
